INSERT INTO jlpt_grammar (pattern, meaning_ko, meaning_ja, jlpt_level, formation, formation_detail, category, example_sentences, usage_notes, sort_order) VALUES
('〜かたがた', '~할 겸, 겸사겸사', '〜を兼ねて、の意の格式表現。', 'N1', '名詞 + かたがた', '「お礼かたがた」「ご挨拶かたがた」 등 격식. 주로 한자어 명사.', 'formal', '[{"ja": "お礼かたがた、ご報告に伺いました。", "ko": "감사 인사도 드릴 겸 보고하러 찾아뵈었습니다.", "highlight": "お礼かたがた"}]', '비즈니스 방문·서신 격식.', 191),
('〜にかまけて', '~에 매달려 / ~에 정신이 팔려', '〜に気を取られて他をおろそかにする。', 'N1', '名詞 + にかまけて', '부정적. 한쪽에 매여 다른 것을 소홀히.', 'reason', '[{"ja": "仕事にかまけて、家庭を顧みなかった。", "ko": "일에 매달려 가정을 돌보지 못했다.", "highlight": "仕事にかまけて"}]', '소홀함에 대한 후회·비판.', 192),
('〜にたえる', '~할 만하다 / ~를 견디다', '〜する価値がある、または持ちこたえる。', 'N1', '動詞辞書形 / 名詞 + にたえる', '「鑑賞にたえる」「批判にたえる」. 부정형 「〜にたえない」은 별도 항목.', 'degree', '[{"ja": "この作品は十分鑑賞にたえる出来だ。", "ko": "이 작품은 충분히 감상할 만한 완성도다.", "highlight": "鑑賞にたえる"}]', '가치·내구성 평가.', 193),
('〜べくして', '필연적으로 ~하다', '当然の結果として〜した、の意。', 'N1', '動詞辞書形 + べくして + 同じ動詞のた形', '「起こるべくして起こった」 형태. する→すべくして.', 'conjecture', '[{"ja": "あの事故は起こるべくして起こった。", "ko": "그 사고는 일어날 수밖에 없어서 일어났다.", "highlight": "起こるべくして起こった"}]', '필연성 강조.', 194),
('〜以外の何ものでもない', '~외에 아무것도 아니다', 'まさに〜だ、と強く断定する。', 'N1', '名詞 + 以外の何ものでもない', '강한 단정. 「〜にほかならない」와 유사.', 'emphasis', '[{"ja": "確認を怠ったのは怠慢以外の何ものでもない。", "ko": "확인을 게을리한 것은 태만 외에 아무것도 아니다.", "highlight": "怠慢以外の何ものでもない"}]', '단정·비판 강조.', 195),
('〜ようにも〜ない', '~하려 해도 ~할 수 없다', '〜しようとしても、事情があってできない。', 'N1', '動詞意向形 + にも + 同動詞の可能形ない', '「行こうにも行けない」. 외부 사정에 의한 불가능.', 'ability', '[{"ja": "資料がなく、調べようにも調べられない。", "ko": "자료가 없어서 알아보려 해도 알아볼 수 없다.", "highlight": "調べようにも調べられない"}]', '사정상의 불가능.', 196),
('〜とはいうものの', '~라고는 하지만', '〜とはいえ、実際は事情が異なる。', 'N1', '普通形 / 名詞 + とはいうものの', '단정 후 단서·역접.', 'contrast', '[{"ja": "締め切りは来週とはいうものの、油断はできない。", "ko": "마감은 다음 주라고는 하지만 방심할 수 없다.", "highlight": "来週とはいうものの"}]', '예상과 현실의 괴리.', 197),
('〜ものとする', '~하기로 한다 (규정)', '規則として〜と定める、の文語。', 'N1', '動詞辞書形 + ものとする', '계약·규정·약관 문어.', 'formal', '[{"ja": "支払いは月末までに行うものとする。", "ko": "지불은 월말까지 하기로 한다.", "highlight": "行うものとする"}]', '계약·규정 조항.', 198),
('〜にかかっている', '~에 달려 있다', '〜次第で結果が決まる。', 'N1', '名詞 / 疑問詞を含む節 + にかかっている', '성패를 좌우하는 요인.', 'condition', '[{"ja": "プロジェクトの成否は準備にかかっている。", "ko": "프로젝트의 성패는 준비에 달려 있다.", "highlight": "準備にかかっている"}]', '결정 요인 강조.', 199),
('〜こそあれ', '~야 있을지언정', '〜はあっても、反対のことはない。', 'N1', '名詞 / 形容詞 + こそあれ', '뒤에 부정. 일방을 강조하는 문어.', 'contrast', '[{"ja": "彼には感謝こそあれ、不満など全くない。", "ko": "그에게는 감사할지언정 불만 따위는 전혀 없다.", "highlight": "感謝こそあれ"}]', '문어. 한쪽 강조.', 200),
('〜てまで', '~하면서까지', 'そこまでして〜する、と程度を強調。', 'N1', '動詞て形 + まで', '극단적 수단. 「〜てまで〜たくない」 자주.', 'degree', '[{"ja": "健康を犠牲にしてまで働きたくない。", "ko": "건강을 희생하면서까지 일하고 싶지 않다.", "highlight": "犠牲にしてまで"}]', '과도한 수단 비판.', 201),
('〜ぐるみ', '~전체 / 통째로', '〜全体を含めて、の意。', 'N1', '名詞 + ぐるみ', '「会社ぐるみ」「家族ぐるみ」「町ぐるみ」.', 'manner', '[{"ja": "会社ぐるみで不正に関与していた。", "ko": "회사 전체가 부정에 관여하고 있었다.", "highlight": "会社ぐるみ"}]', '집단 전체 연루·참여.', 202),
('〜と相まって', '~와 어우러져 / ~와 맞물려', '〜と互いに作用し合って。', 'N1', '名詞 + と相まって', '상승효과. 격식·문어.', 'manner', '[{"ja": "好天と相まって、観光客が急増した。", "ko": "좋은 날씨와 맞물려 관광객이 급증했다.", "highlight": "好天と相まって"}]', '요인 결합의 결과.', 203),
('〜を限りに', '~를 끝으로', '〜を最後として(その後はしない)。', 'N1', '名詞 + を限りに', '「本日を限りに」「今回を限りに」.', 'time', '[{"ja": "当店は本日を限りに閉店いたします。", "ko": "저희 가게는 오늘을 끝으로 폐점합니다.", "highlight": "本日を限りに"}]', '종료·마지막 시점 선언.', 204),
('〜を境に', '~를 경계 / 계기로', '〜を境目として状況が変化する。', 'N1', '名詞 + を境に(して)', '변화의 분기점.', 'time', '[{"ja": "入社を境に、生活が一変した。", "ko": "입사를 계기로 생활이 완전히 바뀌었다.", "highlight": "入社を境に"}]', '전후 대비 변화.', 205),
('〜もそこそこに', '~도 대충 하고 (서둘러)', '〜を十分にせず急いで次のことをする。', 'N1', '名詞 + もそこそこに', '「挨拶もそこそこに」「食事もそこそこに」.', 'manner', '[{"ja": "彼は食事もそこそこに仕事へ戻った。", "ko": "그는 식사도 대충 하고 일하러 돌아갔다.", "highlight": "食事もそこそこに"}]', '서두름·소홀.', 206),
('〜が関の山', '고작 ~정도가 한계', 'せいぜい〜くらいが限度だ。', 'N1', '名詞 / 動詞辞書形 + が関の山', '한계·고작. 부정적 평가.', 'degree', '[{"ja": "今の予算では中古品を買うのが関の山だ。", "ko": "지금 예산으로는 중고품을 사는 것이 고작이다.", "highlight": "買うのが関の山"}]', '능력·여건의 한계.', 207),
('〜てやまない', '간절히 ~하다 / ~해 마지않다', '心から強く〜し続ける。', 'N1', '動詞て形 + やまない', '「願ってやまない」「愛してやまない」. 감정동사와.', 'degree', '[{"ja": "皆様のご活躍を願ってやまない。", "ko": "여러분의 활약을 간절히 바라 마지않습니다.", "highlight": "願ってやまない"}]', '격식 기원·소망.', 208),
('〜ずにはすまない', '~하지 않고는 끝나지 않는다', '社会通念上、必ず〜しなければならない。', 'N1', '動詞ない形の語幹 + ずにはすまない', 'する→せずにはすまない. 「〜ないではすまない」도.', 'emphasis', '[{"ja": "損害を与えた以上、弁償せずにはすまない。", "ko": "손해를 입힌 이상 변상하지 않고는 끝나지 않는다.", "highlight": "弁償せずにはすまない"}]', '도의적·사회적 당위.', 209),
('〜に則って', '~에 준하여 / ~에 따라', '規範・基準に従って。', 'N1', '名詞 + に則って', '「規則に則って」「前例に則って」.', 'manner', '[{"ja": "手続きは規定に則って行います。", "ko": "절차는 규정에 따라 진행합니다.", "highlight": "規定に則って"}]', '규범·기준 준수(격식).', 210),
('〜ながらの', '~그대로의 / ~인 채로의', 'ずっと変わらない〜の状態の。', 'N1', '名詞 / 動詞ます形 + ながらの', '「昔ながらの」「生まれながらの」.', 'manner', '[{"ja": "この店は昔ながらの製法を守っている。", "ko": "이 가게는 옛날 그대로의 제법을 지키고 있다.", "highlight": "昔ながらの"}]', '변치 않은 상태 수식.', 211),
('〜くらいのものだ', '고작 ~정도다 / ~정도밖에 없다', 'せいぜい〜だけだ、と限定する。', 'N1', '名詞 / 動詞辞書形 + くらいのものだ', '한정·드묾.', 'degree', '[{"ja": "文句も言わずやり遂げるのは彼くらいのものだ。", "ko": "불평도 없이 해내는 사람은 그 정도밖에 없다.", "highlight": "彼くらいのものだ"}]', '예외적 한정.', 212),
('〜とは', '~라니 (놀람·어이없음)', '〜とは驚きだ・あきれる、の意。', 'N1', '普通形 / 名詞 + とは', '뒤 술어 생략 자주.', 'emphasis', '[{"ja": "こんなに早く完成するとは、驚きだ。", "ko": "이렇게 빨리 완성되다니 놀랍다.", "highlight": "完成するとは"}]', '의외·감탄·비난.', 213),
('〜得る', '~할 수 있다 / ~할 가능성이 있다', '〜する可能性がある。', 'N1', '動詞ます形 + 得る(うる/える)', '「あり得る」「考え得る」. 부정은 「〜得ない」.', 'ability', '[{"ja": "それは十分起こり得る事態だ。", "ko": "그것은 충분히 일어날 수 있는 사태다.", "highlight": "起こり得る"}]', '가능성(문어). 읽기 うる/える 모두.', 214),
('〜と思いきや', '~인 줄 알았더니 (의외)', '〜と思ったが、実際は違った。', 'N1', '普通形 + と思いきや', '예상이 빗나감.', 'conjecture', '[{"ja": "簡単だと思いきや、意外に手こずった。", "ko": "간단할 줄 알았더니 의외로 애를 먹었다.", "highlight": "簡単だと思いきや"}]', '의외의 결과(회화·서술).', 215),
('〜てからというもの', '~한 이래로 (죽)', '〜して以来、ずっと(状態が続く)。', 'N1', '動詞て形 + からというもの', '변화 후 지속되는 상태.', 'time', '[{"ja": "転職してからというもの、毎日が充実している。", "ko": "이직한 이래로 매일이 알차다.", "highlight": "転職してからというもの"}]', '전환점 이후 지속.', 216),
('〜だの〜だの', '~라느니 ~라느니', 'いくつか例を挙げて述べる(不満が多い)。', 'N1', '名詞 / 普通形 + だの + 〜だの', '부정적 나열이 많음.', 'listing', '[{"ja": "高いだの面倒だのと、文句ばかりだ。", "ko": "비싸다느니 귀찮다느니 불평만 한다.", "highlight": "高いだの面倒だの"}]', '불만·예시 나열.', 217),
('〜ことか', '얼마나 ~한가', 'どれほど〜だろう、と感嘆を表す。', 'N1', '疑問詞 + 普通形 + ことか', '「どんなに〜ことか」「何度〜ことか」.', 'emphasis', '[{"ja": "この日をどれほど待ったことか。", "ko": "이 날을 얼마나 기다렸던가.", "highlight": "待ったことか"}]', '감개·강한 감정.', 218),
('〜ものか', '결코 ~하지 않겠다 (반어)', '絶対に〜しない、という強い否定。', 'N1', '動詞辞書形 + ものか', '회화체 「〜もんか」. 강한 거부.', 'emphasis', '[{"ja": "こんなことで諦めるものか。", "ko": "이런 일로 포기할까 보냐.", "highlight": "諦めるものか"}]', '강한 부정 의지(반어).', 219),
('〜であれ', '~든 / ~라 해도', 'たとえ〜でも、結論は変わらない。', 'N1', '名詞 + であれ', '「理由が何であれ」「どこであれ」.', 'contrast', '[{"ja": "どんな理由であれ、遅刻は遅刻だ。", "ko": "어떤 이유든 지각은 지각이다.", "highlight": "理由であれ"}]', '양보·예외 불인정.', 220);
INSERT INTO jlpt_vocabulary (word, reading, meaning_ko, jlpt_level, part_of_speech, example_sentence, example_sentence_ko) VALUES
('概略', 'がいりゃく', '개략', 'N1', '명사', 'まず計画の概略を説明する。', '먼저 계획의 개략을 설명한다.'),
('進捗', 'しんちょく', '진척', 'N1', '명사', 'プロジェクトの進捗を報告する。', '프로젝트의 진척을 보고한다.'),
('顕在化', 'けんざいか', '현재화, 표면화', 'N1', '명사', '問題が顕在化してきた。', '문제가 표면화되기 시작했다.'),
('潜在', 'せんざい', '잠재', 'N1', '명사', '潜在的なリスクを洗い出す。', '잠재적인 리스크를 가려낸다.'),
('精通', 'せいつう', '정통', 'N1', '명사', '彼は業界の事情に精通している。', '그는 업계 사정에 정통하다.'),
('熟知', 'じゅくち', '숙지', 'N1', '명사', '手順を熟知しておく必要がある。', '절차를 숙지해 둘 필요가 있다.'),
('周知', 'しゅうち', '주지, 널리 알림', 'N1', '명사', '変更点を全社に周知する。', '변경점을 전사에 주지시킨다.'),
('折り合い', 'おりあい', '타협, 절충', 'N1', '명사', '双方が折り合いをつけた。', '양측이 타협점을 찾았다.'),
('駆け引き', 'かけひき', '흥정, 술수', 'N1', '명사', '巧妙な駆け引きで交渉を進める。', '교묘한 흥정으로 협상을 진행한다.'),
('目論見', 'もくろみ', '속셈, 계획', 'N1', '명사', '彼の目論見が外れた。', '그의 속셈이 빗나갔다.'),
('算段', 'さんだん', '변통, 궁리', 'N1', '명사', '資金の算段に頭を悩ませる。', '자금 변통에 골머리를 앓는다.'),
('内幕', 'うちまく', '내막', 'N1', '명사', '事件の内幕が明らかになった。', '사건의 내막이 밝혀졌다.'),
('真相', 'しんそう', '진상', 'N1', '명사', '事故の真相を究明する。', '사고의 진상을 규명한다.'),
('核心', 'かくしん', '핵심', 'N1', '명사', '議論の核心に触れる。', '논의의 핵심을 짚는다.'),
('要衝', 'ようしょう', '요충(지)', 'N1', '명사', 'この港は交通の要衝だ。', '이 항구는 교통의 요충지다.'),
('岐路', 'きろ', '기로, 갈림길', 'N1', '명사', '会社は重大な岐路に立っている。', '회사는 중대한 기로에 서 있다.'),
('局面', 'きょくめん', '국면', 'N1', '명사', '事態は新たな局面を迎えた。', '사태는 새로운 국면을 맞았다.'),
('渦中', 'かちゅう', '와중', 'N1', '명사', '彼はスキャンダルの渦中にいる。', '그는 스캔들의 와중에 있다.'),
('矢面', 'やおもて', '정면, 화살받이', 'N1', '명사', '責任者として矢面に立つ。', '책임자로서 정면에 나선다.'),
('範疇', 'はんちゅう', '범주', 'N1', '명사', 'それは私の専門の範疇外だ。', '그것은 내 전문 범주 밖이다.'),
('系譜', 'けいふ', '계보', 'N1', '명사', '日本画の系譜をたどる。', '일본화의 계보를 더듬는다.'),
('牙城', 'がじょう', '아성', 'N1', '명사', '業界最大手の牙城を崩す。', '업계 최대 기업의 아성을 무너뜨린다.'),
('機運', 'きうん', '기운, 분위기', 'N1', '명사', '改革の機運が高まっている。', '개혁의 기운이 고조되고 있다.'),
('形跡', 'けいせき', '형적, 흔적', 'N1', '명사', '侵入された形跡はない。', '침입된 흔적은 없다.'),
('拗れる', 'こじれる', '꼬이다, 악화되다', 'N1', '동사', '話がすっかり拗れてしまった。', '이야기가 완전히 꼬여 버렸다.'),
('群がる', 'むらがる', '떼지어 모이다', 'N1', '동사', '人々が出口に群がる。', '사람들이 출구에 떼지어 모인다.'),
('漕ぎ着ける', 'こぎつける', '겨우 ~에 다다르다', 'N1', '동사', '何とか合意に漕ぎ着けた。', '간신히 합의에 다다랐다.'),
('食い止める', 'くいとめる', '막아 내다, 저지하다', 'N1', '동사', '被害を最小限に食い止めた。', '피해를 최소한으로 막아 냈다.'),
